ant-on-the-boundary:
class Solution:
    def returnToBoundaryCount(self, nums: List[int]) -> int:
        pos = 0
        cnt = 0
        for x in nums:
            pos += x
            if pos == 0:
                cnt += 1
        return cnt

apple-redistribution-into-boxes:
class Solution:
    def minimumBoxes(self, apple: List[int], capacity: List[int]) -> int:
        total = sum(apple)
        capacity.sort(reverse=True)
        for i, c in enumerate(capacity):
            total -= c
            if total <= 0:
                return i + 1
        return len(capacity)

