binary-tree-tilt:
class Solution:
    def findTilt(self, root: Optional[TreeNode]) -> int:
        self.total = 0
        def go(node):
            if not node:
                return 0
            l = go(node.left)
            r = go(node.right)
            self.total += abs(l - r)
            return l + r + node.val
        go(root)
        return self.total

button-with-longest-push-time:
class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_i = events[0][0]
        best_t = events[0][1]
        for j in range(1, len(events)):
            t = events[j][1] - events[j - 1][1]
            if t > best_t:
                best_t = t
                best_i = events[j][0]
        return best_i

calculate-amount-paid-in-taxes:
class Solution:
    def calculateTax(self, brackets: List[List[int]], income: int) -> float:
        tax = 0.0
        prev = 0
        for upper, pct in brackets:
            if income <= prev:
                break
            taxable = min(income, upper) - prev
            tax += taxable * pct / 100.0
            prev = upper
        return tax

