cells-with-odd-values-in-a-matrix:
class Solution:
    def oddCells(self, m: int, n: int, indices: List[List[int]]) -> int:
        rows = [0] * m
        cols = [0] * n
        for r, c in indices:
            rows[r] ^= 1
            cols[c] ^= 1
        ro = sum(rows)
        co = sum(cols)
        return ro * (n - co) + co * (m - ro)

check-array-formation-through-concatenat:
class Solution:
    def canFormArray(self, arr: List[int], pieces: List[List[int]]) -> bool:
        pos = {p[0]: p for p in pieces}
        i = 0
        while i < len(arr):
            p = pos.get(arr[i])
            if p is None:
                return False
            if arr[i:i + len(p)] != p:
                return False
            i += len(p)
        return True

